/**
 * What the timing engine is expected to reproduce from each wuwalab reference
 * rotation (tests/calculator/rotationTimingReference.test.ts). Our own
 * analysis only: row numbers and reasons, never the rotations' contents,
 * which stay in the gitignored reference/ folder (ADR 0047).
 *
 * Every gap between two rows matches the engine to the frame except the rows
 * listed under `differences`. Reasons:
 * - post-swap wait: the next character starts later than the swap frame.
 *   The frame data doesn't record why (swap cooldowns, landing, positioning).
 * - 1-frame trim: the author's gap is one frame off the ability's length.
 * - echo cast: an echo whose cast takes field time; echo frames aren't in the
 *   character snapshots, so the engine counts it as 0.
 * - instant dash: an "idash" cancel, which isn't always the +22 frames of a dash.
 * - author timing: a gap the author set by hand that no frame-data rule explains.
 */
export type GapReason = "post-swap wait" | "1-frame trim" | "echo cast" | "instant dash" | "author timing";

export interface ReferenceExpectation {
  /** Gaps between rows (rows − 1). */
  gaps: number;
  /** Gaps the engine reproduces to the frame. */
  exact: number;
  /** Row index → why that row's gap differs. */
  differences: Record<number, GapReason>;
}

